from dsl import lesson, P, C, TIP, WARN, EX

PART = 5

lesson("p5-final", PART, "Final challenge: 5 exam-style tasks",
P("These are 5 exam-style tasks. No new theory: everything you need is in Parts 1–2. Try each one **without** opening the hints first. `EX` and `STUDY` exist as usual."),
P("Before writing, ask yourself the 3 questions:\n- What does the answer look like? (a number, a list, True/False)\n- Is it about the whole MDP, one state, or one action?\n- So where does my start value go, and which loops do I need?"),
EX("ex-fin-1", "num_actions(transitions)",
   "Return a list: how many actions each state has.",
   "def num_actions(transitions):\n    pass\n",
   "def num_actions(transitions):\n    result = []\n    for actions in transitions:\n        result.append(len(actions))\n    return result\n",
   ["num_actions(EX)", "num_actions(STUDY)", "num_actions([[[(1.0, 0, 0.0, True)], [(1.0, 0, 0.0, True)], [(1.0, 0, 0.0, True)]]])"],
   ["The answer is per state, and you don't need the outcomes: one loop.", "`for actions in transitions: result.append(len(actions))`"]),
EX("ex-fin-2", "max_reward(transitions)",
   "Return the largest reward of any outcome in the whole MDP.",
   "def max_reward(transitions):\n    pass\n",
   "def max_reward(transitions):\n    best = None\n    for actions in transitions:\n        for outcomes in actions:\n            for prob, next_state, reward, terminal in outcomes:\n                if best is None or reward > best:\n                    best = reward\n    return best\n",
   ["max_reward(EX)", "max_reward(STUDY)", "max_reward([[[(1.0, 0, -3.0, True)], [(1.0, 0, -7.0, True)]]])"],
   ["Whole MDP → triple loop; start value before all loops. Rewards can all be negative.", "`best = None`, then `if best is None or reward > best: best = reward`."]),
EX("ex-fin-3", "deterministic_states(transitions)",
   "Return the list of states where **every** action has exactly one outcome with `prob > 0`.",
   "def deterministic_states(transitions):\n    pass\n",
   "def deterministic_states(transitions):\n    result = []\n    for s, actions in enumerate(transitions):\n        ok = True\n        for outcomes in actions:\n            positive = 0\n            for prob, next_state, reward, terminal in outcomes:\n                if prob > 0:\n                    positive += 1\n            if positive != 1:\n                ok = False\n                break\n        if ok:\n            result.append(s)\n    return result\n",
   ["deterministic_states(EX)", "deterministic_states(STUDY)",
    "deterministic_states([[[(1.0, 0, 0.0, False), (0.0, 1, 0.0, True)]], [[(0.5, 0, 0.0, False), (0.5, 1, 0.0, True)]]])"],
   ["Like `rows_all_positive` (flag `ok`) combined with counting positive outcomes per action like `stochastic_states`.", "Per state: `ok = True`. Per action: count `positive`; if `positive != 1`: `ok = False; break`. After the action loop: `if ok: result.append(s)`."]),
EX("ex-fin-4", "prob_to_reach(transitions, s, a, target)",
   "Return the total probability of landing in state `target` when doing action `a` in state `s`. (Several outcomes may lead to the same state!)",
   "def prob_to_reach(transitions, s, a, target):\n    pass\n",
   "def prob_to_reach(transitions, s, a, target):\n    total = 0.0\n    for prob, next_state, reward, terminal in transitions[s][a]:\n        if next_state == target:\n            total += prob\n    return total\n",
   ["prob_to_reach(EX, 0, 0, 1)", "prob_to_reach(STUDY, 1, 0, 2)", "prob_to_reach(EX, 0, 0, 0)",
    "prob_to_reach([[[(0.3, 1, 0.0, False), (0.2, 1, 5.0, True), (0.5, 0, 0.0, False)]], [[(1.0, 1, 0.0, True)]]], 0, 0, 1)"],
   ["One action → loop over `transitions[s][a]` only.", "`if next_state == target: total += prob` (use `==`, not `=`)."]),
EX("ex-fin-5", "expected_reward(transitions, s, a)",
   "Return the expected immediate reward of action `a` in state `s`: Σ prob × reward.",
   "def expected_reward(transitions, s, a):\n    pass\n",
   "def expected_reward(transitions, s, a):\n    total = 0.0\n    for prob, next_state, reward, terminal in transitions[s][a]:\n        total += prob * reward\n    return total\n",
   ["expected_reward(STUDY, 1, 0)", "expected_reward(EX, 0, 0)", "expected_reward(EX, 0, 1)", "expected_reward(STUDY, 0, 1)"],
   ["One action, accumulator of `prob * reward`.", "Same as `q_value` but without the future part."]),
TIP("If you solved all 5 without the solution button, you are ready for the CodeRunner part of the test. Then do Parts 3–4 again from memory: `q_value`, `value_iteration`, `greedy_policy`, `policy_evaluation`, `q_learning_update`."),
)
